//! Reference LZ4 block vector produced by the `lz4` Python package (high compression mode) for
//! the input `lcg(3000) + lcg(3000)` where `lcg` is the generator in `lcg()` below.

/// Compressed form of the 6000-byte input.
pub const F_HC: &str = "";

/// The generator the reference input was made with: x = x * 1103515245 + 12345 mod 2^31, byte = x >> 16.
pub fn lcg(n: usize) -> Vec<u8> {
    let mut x: u64 = 1;
    (0..n)
        .map(|_| {
            x = (x * 1_103_515_245 + 12345) & 0x7fff_ffff;
            ((x >> 16) & 0xff) as u8
        })
        .collect()
}
